 15 | func (s *AuthService) issueSession(ctx context.Context, admin *models.AdminUser, meta RequestMeta) (*TokenPair, error) {
 16 | 	accessToken, accessExpiresAt, err := s.tokens.IssueAccessToken(admin)
 17 | 	if err != nil {
 18 | 		return nil, wrapErr(err, 500, "internal_error", "Could not create a session.")
 19 | 	}
